#!/usr/bin/env python3
"""Check the runtime configuration generated by XMLGenerator against the frozen
formulation (what will actually execute, not just what the deck says).

Usage: check_generated_config.py RUNDIR --mesh M --max-iterations N
         (--symmetry-sides ss_sym | --no-symmetry-sides) [--sym-bc-sideset ss_sym]
         [--simp-min 1e-3] [--simp-exp 3.0] [--radius 0.15] [--sticking 1.0]
         [--volume-target 0.15] [--write-restart true|false]
         (--initial-density 0.15 | --restart-file F --restart-field control --restart-iteration K)
         --out JSON
Exit 0 if every check passes, 1 otherwise.  Prints PASS/FAIL lines and a summary.
"""
import argparse, json, math, os, re, sys
import xml.etree.ElementTree as ET

ap = argparse.ArgumentParser()
ap.add_argument("rundir")
ap.add_argument("--mesh", required=True)
ap.add_argument("--max-iterations", type=int, required=True)
ap.add_argument("--symmetry-sides")
ap.add_argument("--no-symmetry-sides", action="store_true")
ap.add_argument("--sym-bc-sideset")
ap.add_argument("--simp-min", type=float, default=1e-3)
ap.add_argument("--simp-exp", type=float, default=3.0)
ap.add_argument("--radius", type=float, default=0.15)
ap.add_argument("--sticking", type=float, default=1.0)
ap.add_argument("--volume-target", type=float, default=0.15)
ap.add_argument("--write-restart", choices=["true", "false"])
ap.add_argument("--initial-density", type=float)
ap.add_argument("--restart-file")
ap.add_argument("--restart-field")
ap.add_argument("--restart-iteration", type=int)
ap.add_argument("--update-frequency", type=int, default=1)
ap.add_argument("--out", required=True)
a = ap.parse_args()
R = a.rundir
checks, info = {}, {}


def pl(path):
    return ET.parse(os.path.join(R, path)).getroot()


def params(node):
    out = {}
    for lst in node.iter("ParameterList"):
        for p in lst.findall("Parameter"):
            out.setdefault(lst.get("name"), {})[p.get("name")] = p.get("value")
    return out


def feq(x, y, rel=1e-4):
    try:
        return abs(float(x) - float(y)) <= rel * max(1.0, abs(float(y)))
    except (TypeError, ValueError):
        return False


# ---- Helmholtz filter deck ------------------------------------------------
h = params(pl("analyze_helmholtz_input_deck.xml"))
hp = h.get("Parameters", {})
info["helmholtz"] = {"Input Mesh": h.get("Problem", {}).get("Input Mesh"), "Physics": h.get("Scenarios", {}).get("Physics"), **hp}
checks["helmholtz: Physics == Helmholtz Filter"] = h.get("Scenarios", {}).get("Physics") == "Helmholtz Filter"
checks["helmholtz: Input Mesh == mesh"] = h.get("Problem", {}).get("Input Mesh") == a.mesh
ls_expected = a.radius / (2.0 * math.sqrt(3.0))
checks[f"helmholtz: Length Scale == radius/(2*sqrt(3)) = {ls_expected:.6f}"] = feq(hp.get("Length Scale"), ls_expected, 2e-4)
checks[f"helmholtz: Surface Length Scale == {a.sticking}"] = feq(hp.get("Surface Length Scale"), a.sticking)
sps = hp.get("Symmetry Plane Sides")
if a.symmetry_sides:
    checks[f"helmholtz: Symmetry Plane Sides == {{{a.symmetry_sides}}}"] = sps == "{%s}" % a.symmetry_sides
elif a.no_symmetry_sides:
    checks["helmholtz: no Symmetry Plane Sides"] = sps is None

# ---- analyze physics deck -------------------------------------------------
root = pl("analyze_2_input_deck.xml")
p = params(root)
checks["analyze: Physics == Mechanical"] = p.get("Scenarios", {}).get("Physics") == "Mechanical"
checks["analyze: Input Mesh == mesh"] = p.get("Problem", {}).get("Input Mesh") == a.mesh
mat = p.get("Isotropic Linear Elastic", {})
info["material"] = mat
checks["analyze: Youngs Modulus == 1.0"] = feq(mat.get("Youngs Modulus"), 1.0)
checks["analyze: Poissons Ratio == 0.3"] = feq(mat.get("Poissons Ratio"), 0.3)
res = [l for l in root.iter("ParameterList") if l.get("name") == "Mechanical Residual"]
pen = {q.get("name"): q.get("value") for l in res for pf in l.findall("ParameterList") if pf.get("name") == "Penalty Function" for q in pf.findall("Parameter")}
info["residual_penalty"] = pen
checks["analyze: residual penalty SIMP"] = pen.get("Type") == "SIMP"
checks[f"analyze: residual SIMP Exponent == {a.simp_exp}"] = feq(pen.get("Exponent"), a.simp_exp)
checks[f"analyze: residual SIMP Minimum Value == {a.simp_min:g}"] = feq(pen.get("Minimum Value"), a.simp_min, 1e-6)
obj = [l for l in root.iter("ParameterList") if l.get("name") == "My Objective"]
objp = {q.get("name"): q.get("value") for l in obj for q in l.findall("Parameter")}
objpen = {q.get("name"): q.get("value") for l in obj for pf in l.findall("ParameterList") if pf.get("name") == "Penalty Function" for q in pf.findall("Parameter")}
info["objective"] = {**objp, "penalty": objpen}
checks["analyze: objective == Internal Elastic Energy (compliance)"] = objp.get("Scalar Function Type") == "Internal Elastic Energy"
checks[f"analyze: objective SIMP Exponent == {a.simp_exp}"] = feq(objpen.get("Exponent"), a.simp_exp)
checks[f"analyze: objective SIMP Minimum Value == {a.simp_min:g}"] = feq(objpen.get("Minimum Value"), a.simp_min, 1e-6)
loads = [l for l in root.iter("ParameterList") if re.match(r"Concentrated Load with ID", l.get("name", ""))]
lp = [{q.get("name"): q.get("value") for q in l.findall("Parameter")} for l in loads]
info["loads"] = lp
checks["analyze: exactly one concentrated load"] = len(lp) == 1
checks["analyze: load Dof 1 (y), Value -1, Nodes ns_load"] = bool(lp) and lp[0].get("Dof") == "1" and feq(lp[0].get("Value"), -1.0) and lp[0].get("Nodes") == "ns_load"
ebc = [l for l in root.iter("ParameterList") if l.get("name") == "Essential Boundary Conditions"]
bcs = [{q.get("name"): q.get("value") for q in l.findall("Parameter")} for e in ebc for l in e.findall("ParameterList")]
info["essential_bcs"] = bcs
fixed = {(b.get("Index"), b.get("Sides")) for b in bcs if b.get("Type") == "Fixed Value" and feq(b.get("Value"), 0.0)}
checks["analyze: dispx/dispy/dispz = 0 on ns_fix"] = {("0", "ns_fix"), ("1", "ns_fix"), ("2", "ns_fix")} <= fixed
if a.sym_bc_sideset:
    checks[f"analyze: dispz = 0 on {a.sym_bc_sideset}"] = ("2", a.sym_bc_sideset) in fixed
    checks["analyze: exactly 4 essential BCs"] = len(bcs) == 4
else:
    checks["analyze: exactly 3 essential BCs"] = len(bcs) == 3
nat = [l for l in root.iter("ParameterList") if l.get("name") == "Mechanical Natural Boundary Conditions"]
checks["analyze: no natural (traction) BCs"] = all(len(list(l)) == 0 for l in nat)
info["solver"] = p.get("Solver Options", {})
checks["analyze: output dispx dispy dispz"] = "displacement_x" in (p.get("Output", {}).get("Plottable") or "")

# ---- interface.xml (multiple roots) ----------------------------------------
txt = open(os.path.join(R, "interface.xml")).read()
iroot = ET.fromstring("<root>" + re.sub(r"<\?xml[^>]*\?>", "", txt) + "</root>")
opt = iroot.find("Optimizer")
info["optimizer"] = {}
checks["interface: Optimizer Package == OC"] = opt is not None and opt.findtext("Package") == "OC"
mi = opt.findtext("Convergence/MaxIterations") if opt is not None else None
info["optimizer"]["MaxIterations"] = mi
checks[f"interface: MaxIterations == {a.max_iterations}"] = mi == str(a.max_iterations)
for k in ("OCControlStagnationTolerance", "OCObjectiveStagnationTolerance", "OCGradientTolerance", "ProblemUpdateFrequency"):
    info["optimizer"][k] = opt.findtext(f"Options/{k}") if opt is not None else None
checks[f"interface: ProblemUpdateFrequency == {a.update_frequency}"] = info["optimizer"]["ProblemUpdateFrequency"] == str(a.update_frequency)
con = opt.find("Constraint") if opt is not None else None
ntv = con.findtext("NormalizedTargetValue") if con is not None else None
info["optimizer"]["NormalizedTargetValue"] = ntv
checks[f"interface: volume NormalizedTargetValue == {a.volume_target}"] = feq(ntv, a.volume_target)
checks["interface: constraint ReferenceValueName == Design Volume"] = con is not None and con.findtext("ReferenceValueName") == "Design Volume"
bc = opt.find("BoundConstraint") if opt is not None else None
checks["interface: bounds [0,1]"] = bc is not None and feq(bc.findtext("Lower"), 0.0) and feq(bc.findtext("Upper"), 1.0)
perf = [(x.findtext("Name"), x.findtext("Code")) for x in iroot.findall("Performer")]
info["performers"] = perf
checks["interface: performers engine_1, analyze_2, analyze_helmholtz"] = [n for n, _ in perf] == ["engine_1", "analyze_2", "analyze_helmholtz"]

# ---- engine_operations.xml (multiple roots) --------------------------------
etxt = open(os.path.join(R, "engine_operations.xml")).read()
eroot = ET.fromstring("<root>" + re.sub(r"<\?xml[^>]*\?>", "", etxt) + "</root>")
ops = {o.findtext("Function"): o for o in eroot.findall("Operation")}
pmo = ops.get("PlatoMainOutput")
info["engine_output"] = {"WriteRestart": pmo.findtext("WriteRestart") if pmo is not None else None,
                         "OutputFrequency": pmo.findtext("OutputFrequency") if pmo is not None else None,
                         "MaxIterations": pmo.findtext("MaxIterations") if pmo is not None else None,
                         "RestartFieldName": pmo.findtext("RestartFieldName") if pmo is not None else None}
if a.write_restart:
    checks[f"engine: PlatoMainOutput WriteRestart == {a.write_restart}"] = info["engine_output"]["WriteRestart"] == a.write_restart
checks[f"engine: PlatoMainOutput MaxIterations == {a.max_iterations}"] = info["engine_output"]["MaxIterations"] == str(a.max_iterations)
init = ops.get("InitializeField")
info["initialize_field"] = {"Method": init.findtext("Method") if init is not None else None}
if a.initial_density is not None:
    val = init.findtext("Uniform/Value") if init is not None else None
    info["initialize_field"]["Uniform/Value"] = val
    checks[f"engine: InitializeField Uniform {a.initial_density}"] = init is not None and init.findtext("Method") == "Uniform" and feq(val, a.initial_density)
if a.restart_file:
    ff = init.find("FromFieldOnInputMesh") if init is not None else None
    info["initialize_field"].update({"Name": ff.findtext("Name") if ff is not None else None,
                                     "VariableName": ff.findtext("VariableName") if ff is not None else None,
                                     "Iteration": ff.findtext("Iteration") if ff is not None else None})
    checks["engine: InitializeField Method == FromFieldOnInputMesh"] = init is not None and init.findtext("Method") == "FromFieldOnInputMesh"
    checks[f"engine: restart file == {a.restart_file}"] = ff is not None and ff.findtext("Name") == a.restart_file
    checks[f"engine: restart field == {a.restart_field}"] = ff is not None and ff.findtext("VariableName") == a.restart_field
    checks[f"engine: restart Iteration (1-based Exodus state) == {a.restart_iteration}"] = ff is not None and ff.findtext("Iteration") == str(a.restart_iteration)
upd = ops.get("Update Problem")
checks[f"engine: UpdateProblemFrequency == {a.update_frequency}"] = upd is not None and upd.findtext("UpdateProblemFrequency") == str(a.update_frequency)

# ---- mpirun.source -------------------------------------------------------
m = open(os.path.join(R, "mpirun.source")).read()
nps = re.findall(r"-np\s+(\d+)", m)
info["mpirun_np"] = nps
checks["mpirun: three single-rank performers (PlatoMain, analyze, helmholtz)"] = nps == ["1", "1", "1"] and m.count("analyze_MPMD") == 2 and "PlatoMain" in m

rep = {"rundir": os.path.abspath(R), "args": vars(a), "info": info, "checks": {k: bool(v) for k, v in checks.items()},
       "n_pass": sum(bool(v) for v in checks.values()), "n_checks": len(checks), "all_checks_pass": all(checks.values())}
json.dump(rep, open(a.out, "w"), indent=2)
for k, v in checks.items():
    print(("PASS " if v else "FAIL ") + k)
print(f"{rep['n_pass']}/{rep['n_checks']} checks pass; all_checks_pass={rep['all_checks_pass']}")
sys.exit(0 if rep["all_checks_pass"] else 1)
